package nl.smartstreamlabs.sbwdroneconfig;
import java.util.*;import net.minecraft.core.BlockPos;import net.minecraft.nbt.CompoundTag;import net.minecraft.world.*;import net.minecraft.world.phys.Vec3;import net.minecraft.world.entity.Entity;import net.minecraft.server.level.*;import net.minecraft.network.chat.Component;import net.minecraft.util.Mth;import com.atsuishio.superbwarfare.entity.vehicle.base.VehicleEntity;
public final class RescueCoupling {
 private record Pair(SupplyRoverEntity rover,MedicalTrailerEntity trailer){}private static final Map<UUID,Pair> PAIRS=new HashMap<>();
 private record Selection(UUID first,UUID second,long until){}private static final Map<UUID,Selection> SELECTED=new HashMap<>();private static final Set<UUID> PACK_RELEASE=new HashSet<>();private static final Map<UUID,Integer> MISSING=new HashMap<>();
 public static Vec3 point(VehicleEntity e,double x,double y,double z){var v=e.transformPosition(e.getVehicleTransform(1),x,y,z);return new Vec3(v.x,v.y,v.z);}
 public static RescueVehicle other(RescueVehicle v){if(v.partner()==null)return null;if(v.unit().level() instanceof ServerLevel l)return l.getEntity(v.partner()) instanceof RescueVehicle o?o:null;var found=v.unit().level().getEntitiesOfClass(Entity.class,v.unit().getBoundingBox().inflate(12),e->e instanceof RescueVehicle&&e.getUUID().equals(v.partner()));return found.isEmpty()?null:(RescueVehicle)found.get(0);}
 public static boolean trackedBy(ServerPlayer p,Entity e){if(!(e instanceof MedicalTrailerEntity t))return false;var o=other(t);return o instanceof SupplyRoverEntity r&&VatagSessions.controlling(p,r);}
 public static void save(RescueVehicle v,CompoundTag n){if(v.partner()!=null){n.putUUID("RescuePartner",v.partner());n.putLong("RescuePartnerPosition",v.lastPartnerPosition().asLong());}}
 public static void load(RescueVehicle v,CompoundTag n){v.partner(n.hasUUID("RescuePartner")?n.getUUID("RescuePartner"):null,BlockPos.of(n.getLong("RescuePartnerPosition")));}
 public static void detach(RescueVehicle v){var o=other(v);if(o!=null&&v.unit().getUUID().equals(o.partner())){o.partner(null,BlockPos.ZERO);ChunkTicketManager.releaseDrone(o.unit());}v.partner(null,BlockPos.ZERO);ChunkTicketManager.releaseDrone(v.unit());MISSING.remove(v.unit().getUUID());}
 private static void message(ServerPlayer p,String s){p.displayClientMessage(Component.literal(s),true);}
 public static InteractionResult tool(ServerPlayer p,RescueVehicle v,InteractionHand h){if(!p.getItemInHand(h).is(com.atsuishio.superbwarfare.init.ModTags.Items.TOOLS_CROWBAR))return null;
  if(!v.permitted(p)||p.distanceToSqr(v.unit())>36)return InteractionResult.FAIL;
  if(!p.isShiftKeyDown())PACK_RELEASE.remove(p.getUUID());else if(PACK_RELEASE.contains(p.getUUID()))return InteractionResult.CONSUME;
  if(p.isShiftKeyDown()&&v.partner()!=null){var armed=SELECTED.get(p.getUUID());if(armed==null||!armed.first.equals(v.unit().getUUID())||!armed.first.equals(armed.second)||armed.until<p.serverLevel().getGameTime()){message(p,"To disconnect: right-click without sneaking, then sneak + right-click to confirm.");return InteractionResult.CONSUME;}if(v.unit().getDeltaMovement().horizontalDistance()>.035){message(p,"Stop before uncoupling.");return InteractionResult.FAIL;}detach(v);SELECTED.remove(p.getUUID());PACK_RELEASE.add(p.getUUID());message(p,"Uncoupled. Cargo and patient remain in place. Sneak + crowbar again to pack an empty vehicle.");return InteractionResult.CONSUME;}
  Selection s=SELECTED.get(p.getUUID());if(s!=null&&s.until<p.serverLevel().getGameTime()){SELECTED.remove(p.getUUID());s=null;}
  if(p.isShiftKeyDown()&&s!=null&&s.second!=null&&s.second.equals(v.unit().getUUID())){
   var first=p.serverLevel().getEntity(s.first);if(!(first instanceof RescueVehicle a)||!a.permitted(p)||a.unit().distanceToSqr(p)>36||a.unit().level()!=v.unit().level()||a.unit().isRemoved()||v.unit().isRemoved()||a.unit().isWreck()||v.unit().isWreck()||a.partner()!=null||v.partner()!=null||a.getClass()==v.getClass()||a.hitch().distanceTo(v.hitch())>1.25||Math.abs(Mth.wrapDegrees(a.unit().getYRot()-v.unit().getYRot()))>55||a.unit().getDeltaMovement().length()>.04||v.unit().getDeltaMovement().length()>.04){message(p,"Cannot couple: check ownership, empty hitch, distance and stopped vehicles.");SELECTED.remove(p.getUUID());return InteractionResult.FAIL;}
   a.claim(p);v.claim(p);a.partner(v.unit().getUUID(),v.unit().blockPosition());v.partner(a.unit().getUUID(),a.unit().blockPosition());SELECTED.remove(p.getUUID());message(p,"SR-01 and MT-01 coupled. Sneak + crowbar to disconnect.");return InteractionResult.CONSUME;
  }
  if(p.isShiftKeyDown()){if(v.occupied()){message(p,"Unload the patient before packing.");return InteractionResult.FAIL;}return null;}
  if(v.partner()!=null){SELECTED.put(p.getUUID(),new Selection(v.unit().getUUID(),v.unit().getUUID(),p.serverLevel().getGameTime()+600));message(p,"Confirm disconnect: sneak + right-click this vehicle with crowbar.");return InteractionResult.CONSUME;}
  v.claim(p);if(s==null||s.first.equals(v.unit().getUUID())){SELECTED.put(p.getUUID(),new Selection(v.unit().getUUID(),null,p.serverLevel().getGameTime()+600));message(p,(v instanceof SupplyRoverEntity?"SR-01 selected (1/3). Right-click MT-01 with the crowbar.":"MT-01 selected (1/3). Right-click SR-01 with the crowbar."));}
  else {SELECTED.put(p.getUUID(),new Selection(s.first,v.unit().getUUID(),p.serverLevel().getGameTime()+600));message(p,"Step 3/3: Shift + right-click this vehicle with the crowbar to confirm coupling. Both hitches must be within 1.25 blocks.");}return InteractionResult.CONSUME;
 }
 private static final Map<ServerPlayer,Long> REMOTE_RATE=new WeakHashMap<>();
 public static void remoteToggle(ServerPlayer p,SupplyRoverEntity r){long now=p.serverLevel().getGameTime();if(now-REMOTE_RATE.getOrDefault(p,-100L)<10)return;REMOTE_RATE.put(p,now);if(!VatagSessions.controlling(p,r)||!r.permitted(p)||r.getDeltaMovement().length()>.04){message(p,"Stop SR-01 before coupling or uncoupling.");return;}if(r.partner()!=null){detach(r);message(p,"MT-01 uncoupled; cargo and patient remain in place.");return;}MedicalTrailerEntity best=null;double nearest=1.25*1.25;for(var t:p.serverLevel().getEntitiesOfClass(MedicalTrailerEntity.class,r.getBoundingBox().inflate(5))){double d=r.hitch().distanceToSqr(t.hitch());if(t.permitted(p)&&t.partner()==null&&!t.isRemoved()&&!t.isWreck()&&t.getDeltaMovement().length()<=.04&&Math.abs(Mth.wrapDegrees(r.getYRot()-t.getYRot()))<=55&&d<=nearest){best=t;nearest=d;}}if(best==null){message(p,"Align MT-01 behind SR-01: stop both vehicles, hitches within 1.25 blocks, same direction.");return;}r.claim(p);best.claim(p);r.partner(best.getUUID(),best.blockPosition());best.partner(r.getUUID(),r.blockPosition());message(p,"SR-01 and MT-01 coupled.");}
  public static void tick(RescueVehicle v){var e=v.unit();if(v.partner()==null)return;var o=other(v);
  if(o==null){if(e.level().hasChunkAt(v.lastPartnerPosition())&&MISSING.merge(e.getUUID(),1,Integer::sum)>100)detach(v);return;}
  MISSING.remove(e.getUUID());if(!e.getUUID().equals(o.partner())||e.isWreck()||o.unit().isRemoved()||o.unit().isWreck()){detach(v);return;}if(e.tickCount%10==0)v.partner(o.unit().getUUID(),o.unit().blockPosition());
  if(!(v instanceof SupplyRoverEntity r)||!(o instanceof MedicalTrailerEntity t))return;
  var prior=PAIRS.get(r.getUUID());if(prior==null||prior.rover!=r||prior.trailer!=t)PAIRS.put(r.getUUID(),new Pair(r,t));
 }
 public static void step(){for(var pair:List.copyOf(PAIRS.values())){var r=pair.rover;var t=pair.trailer;if(r.isRemoved()||t.isRemoved()||r.level()!=t.level()||r.partner()==null||t.partner()==null||!r.partner().equals(t.getUUID())||!t.partner().equals(r.getUUID())){PAIRS.remove(r.getUUID());continue;}solve(r,t);}}
 private static void solve(SupplyRoverEntity r,MedicalTrailerEntity t){if(r.operator()!=null)ChunkTicketManager.touchDrone(t,1);HitchJoint.flush(r,t);}
 public static void clear(ServerPlayer p){SELECTED.remove(p.getUUID());PACK_RELEASE.remove(p.getUUID());if(p.getVehicle() instanceof MedicalTrailerEntity t){t.forcedExit=true;p.stopRiding();t.forcedExit=false;}}
 public static void forget(UUID id){HitchJoint.forget(id);MISSING.remove(id);PAIRS.entrySet().removeIf(e->e.getKey().equals(id)||e.getValue().trailer.getUUID().equals(id));}
 public static void releasedSneak(ServerPlayer p){if(!p.isShiftKeyDown())PACK_RELEASE.remove(p.getUUID());}
 public static void clearAll(){HitchJoint.clear();SELECTED.clear();MISSING.clear();PACK_RELEASE.clear();PAIRS.clear();}
}
